        fn dropbear_light_exists_for_entity(
            world_ptr: u64,
            entity_id: u64,
        ) -> Result<bool, crate::scripting::native::DropbearNativeError> {
            let world = {
                let ptr = world_ptr as *const World;
                if ptr.is_null() {
                    return Err(
                        crate::scripting::native::DropbearNativeError::NullPointer,
                    );
                }
                let addr = ptr as usize;
                let align = std::mem::align_of::<World>();
                if addr % align != 0 {
                    return Err(
                        crate::scripting::native::DropbearNativeError::InvalidArgument,
                    );
                }
                unsafe { &*ptr }
            };
            if let Ok(entity) = convert_entity(entity_id) {
                Ok(shared::light_exists_for_entity(world, entity))
            } else {
                Ok(false)
            }
        }
