        fn dropbear_light_set_direction(
            world_ptr: u64,
            entity_id: u64,
            direction: NVector3,
        ) -> Result<(), crate::scripting::native::DropbearNativeError> {
            let world = {
                let ptr = world_ptr as *mut World;
                if ptr.is_null() {
                    return Err(
                        crate::scripting::native::DropbearNativeError::NullPointer,
                    );
                }
                let addr = ptr as usize;
                let align = std::mem::align_of::<World>();
                if addr % align != 0 {
                    return Err(
                        crate::scripting::native::DropbearNativeError::InvalidArgument,
                    );
                }
                unsafe { &mut *ptr }
            };
            let entity = convert_entity(entity_id)?;
            let dir = DVec3::from(direction);
            let desired = dir.normalize_or_zero();
            if desired.length_squared() < 1e-12 {
                return Err(DropbearNativeError::InvalidArgument);
            }
            let forward = DVec3::new(0.0, 0.0, -1.0);
            let rotation = DQuat::from_rotation_arc(forward, desired);
            if !set_transform_rotation(world, entity, rotation) {
                return Err(DropbearNativeError::NoSuchComponent);
            }
            Ok(())
        }
