    fn collect_nodes(
        dir: impl AsRef<Path>,
        project_path: impl AsRef<Path>,
        exclude_list: &[&str],
    ) -> Vec<Node> {
        let mut nodes = Vec::new();
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                let entry_path = entry.path();
                let name = entry_path
                    .file_name()
                    .unwrap_or_default()
                    .to_string_lossy()
                    .to_string();
                if entry_path.is_dir()
                    && exclude_list.iter().any(|ex| ex.to_string() == *name)
                {
                    {
                        {
                            let lvl = ::log::Level::Debug;
                            if lvl <= ::log::STATIC_MAX_LEVEL
                                && lvl <= ::log::max_level()
                            {
                                ::log::__private_api::log(
                                    { ::log::__private_api::GlobalLogger },
                                    format_args!("Skipped past folder {0:?}", name),
                                    lvl,
                                    &(
                                        "eucalyptus_core::config",
                                        "eucalyptus_core::config",
                                        ::log::__private_api::loc(),
                                    ),
                                    (),
                                );
                            }
                        }
                    };
                    continue;
                }
                if entry_path.is_dir() {
                    let folder_nodes = collect_nodes(
                        &entry_path,
                        project_path.as_ref(),
                        exclude_list,
                    );
                    nodes
                        .push(
                            Node::Folder(Folder {
                                name,
                                path: entry_path.clone(),
                                nodes: folder_nodes,
                            }),
                        );
                } else {
                    let parent_folder = entry_path
                        .parent()
                        .and_then(|p| p.file_name())
                        .map(|n| n.to_string_lossy().to_lowercase())
                        .unwrap_or_default();
                    let resource_type = if parent_folder.contains("model") {
                        ResourceType::Model
                    } else if parent_folder.contains("texture") {
                        ResourceType::Texture
                    } else if parent_folder.contains("shaders") {
                        ResourceType::Shader
                    } else if entry_path
                        .extension()
                        .map(|e| e.to_string_lossy().to_lowercase())
                        == Some("kt".to_string())
                    {
                        ResourceType::Script
                    } else if entry_path
                        .extension()
                        .map(|e| e.to_string_lossy().to_lowercase().contains("eu"))
                        .unwrap_or_default()
                    {
                        ResourceType::Config
                    } else {
                        ResourceType::Unknown
                    };
                    let relative_path = entry_path
                        .strip_prefix(project_path.as_ref())
                        .unwrap_or(&entry_path)
                        .to_path_buf();
                    nodes
                        .push(
                            Node::File(File::ResourceFile {
                                name,
                                path: relative_path,
                                resource_type,
                            }),
                        );
                }
            }
        }
        nodes
    }
