pub mod logging {
    //! This crate will allow for logging to specific locations. Essentially, just removing boilerplate
    //!
    //! # Supported logging locations:
    //! - Toasts (egui)
    //! - Console
    //! - File (to be implemented)
    use std::fmt::{Display, Formatter};
    use once_cell::sync::Lazy;
    use parking_lot::Mutex;
    pub static LOG_LEVEL: Lazy<Mutex<LogLevel>> = Lazy::new(|| Mutex::new(
        LogLevel::default(),
    ));
    /// LogLevel as shown in LogLevel.kt in the dropbear engine jar library
    pub enum LogLevel {
        TRACE,
        DEBUG,
        #[default]
        INFO,
        WARN,
        ERROR,
    }
    #[automatically_derived]
    impl ::core::default::Default for LogLevel {
        #[inline]
        fn default() -> LogLevel {
            Self::INFO
        }
    }
    impl Display for LogLevel {
        fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
            match self {
                LogLevel::TRACE => f.write_fmt(format_args!("TRACE")),
                LogLevel::DEBUG => f.write_fmt(format_args!("DEBUG")),
                LogLevel::INFO => f.write_fmt(format_args!("INFO")),
                LogLevel::WARN => f.write_fmt(format_args!("WARN")),
                LogLevel::ERROR => f.write_fmt(format_args!("ERROR")),
            }
        }
    }
}
