            pub fn get_exception(env: &mut JNIEnv) -> anyhow::Result<()> {
                if let Ok(ex) = env.exception_occurred() {
                    if ex.is_null() {
                        return Ok(());
                    }
                    env.exception_clear()?;
                    let message_result = env
                        .call_method(&ex, "toString", "()Ljava/lang/String;", &[])?;
                    let message_obj = message_result.l()?;
                    let message_jstring = JString::from(message_obj);
                    let message_str: String = env.get_string(&message_jstring)?.into();
                    let stack_trace_result = env
                        .call_method(
                            &ex,
                            "getStackTrace",
                            "()[Ljava/lang/StackTraceElement;",
                            &[],
                        )?;
                    let stack_trace_obj = stack_trace_result.l()?;
                    let stack_trace_array = JObjectArray::from(stack_trace_obj);
                    let stack_len = env.get_array_length(&stack_trace_array)?;
                    let mut error_msg = ::alloc::__export::must_use({
                        ::alloc::fmt::format(format_args!("{0}\n", message_str))
                    });
                    for i in 0..stack_len {
                        let element = env
                            .get_object_array_element(&stack_trace_array, i)?;
                        let element_str_result = env
                            .call_method(
                                &element,
                                "toString",
                                "()Ljava/lang/String;",
                                &[],
                            )?;
                        let element_str_obj = element_str_result.l()?;
                        let element_jstring = JString::from(element_str_obj);
                        let element_string: String = env
                            .get_string(&element_jstring)?
                            .into();
                        error_msg
                            .push_str(
                                &::alloc::__export::must_use({
                                    ::alloc::fmt::format(
                                        format_args!("  at {0}\n", element_string),
                                    )
                                }),
                            );
                    }
                    let cause_result = env
                        .call_method(&ex, "getCause", "()Ljava/lang/Throwable;", &[])?;
                    let cause_obj = cause_result.l()?;
                    if !cause_obj.is_null() {
                        let cause_str_result = env
                            .call_method(
                                &cause_obj,
                                "toString",
                                "()Ljava/lang/String;",
                                &[],
                            )?;
                        let cause_str_obj = cause_str_result.l()?;
                        let cause_jstring = JString::from(cause_str_obj);
                        let cause_string: String = env
                            .get_string(&cause_jstring)?
                            .into();
                        error_msg
                            .push_str(
                                &::alloc::__export::must_use({
                                    ::alloc::fmt::format(
                                        format_args!("Caused by: {0}\n", cause_string),
                                    )
                                }),
                            );
                    }
                    return Err(
                        ::anyhow::Error::msg(
                            ::alloc::__export::must_use({
                                ::alloc::fmt::format(
                                    format_args!("Java exception: {0}", error_msg),
                                )
                            }),
                        ),
                    );
                }
                Ok(())
            }
