    pub fn search_nodes_recursively<'a, F>(
        nodes: &'a [Node],
        matcher: &F,
        results: &mut Vec<&'a Node>,
    )
    where
        F: Fn(&Node) -> bool,
    {
        for node in nodes {
            if matcher(node) {
                results.push(node);
            }
            match node {
                Node::File(_) => {}
                Node::Folder(folder) => {
                    search_nodes_recursively(&folder.nodes, matcher, results);
                }
            }
        }
    }
    /// Progress events for project creation
    pub enum ProjectProgress {
        Step { _progress: f32, _message: String },
        #[allow(dead_code)]
        Error(String),
        Done,
    }
    pub enum ViewportMode {
        None,
        CameraMove,
        Gizmo,
    }
    #[automatically_derived]
    impl ::core::clone::Clone for ViewportMode {
        #[inline]
        fn clone(&self) -> ViewportMode {
            match self {
                ViewportMode::None => ViewportMode::None,
                ViewportMode::CameraMove => ViewportMode::CameraMove,
                ViewportMode::Gizmo => ViewportMode::Gizmo,
            }
        }
    }
