            pub fn get_rigidbody_children(
                physics: &PhysicsState,
                rb_context: RigidBodyContext,
            ) -> DropbearNativeResult<Vec<ColliderFFI>> {
                let handle = RigidBodyHandle::from_raw_parts(
                    rb_context.index.index,
                    rb_context.index.generation,
                );
                if let Some(rb) = physics.bodies.get(handle) {
                    let children = rb.colliders().to_vec();
                    let mut result = Vec::new();
                    for c in children {
                        let (idx, generation) = c.into_raw_parts();
                        let label_opt = physics
                            .colliders_entity_map
                            .iter()
                            .find_map(|(l, s)| {
                                for (_, h) in s {
                                    if c == *h {
                                        return Some(l.clone());
                                    }
                                }
                                None
                            });
                        if let Some(label) = label_opt {
                            if let Some(entity_id) = physics
                                .entity_label_map
                                .iter()
                                .find_map(|(e, l)| if *l == label { Some(e) } else { None })
                            {
                                result
                                    .push(ColliderFFI {
                                        index: IndexNative {
                                            index: idx,
                                            generation,
                                        },
                                        entity_id: entity_id.to_bits().get(),
                                        id: idx,
                                    });
                            }
                        }
                    }
                    Ok(result)
                } else {
                    Err(DropbearNativeError::PhysicsObjectNotFound)
                }
            }
