                let mut indices = Vec::new();
                for lat in 0..=lat_segments {
                    let theta = std::f32::consts::PI * lat as f32 / lat_segments as f32;
                    let sin_theta = theta.sin();
                    let cos_theta = theta.cos();
                    for lon in 0..=lon_segments {
                        let phi = 2.0 * std::f32::consts::PI * lon as f32
                            / lon_segments as f32;
                        let sin_phi = phi.sin();
                        let cos_phi = phi.cos();
                        let x = radius * sin_theta * cos_phi;
                        let y = radius * cos_theta;
                        let z = radius * sin_theta * sin_phi;
                        vertices.push([x, y, z]);
                    }
                }
                for lat in 0..lat_segments {
                    for lon in 0..lon_segments {
                        let first = (lat * (lon_segments + 1) + lon) as u16;
                        let second = first + lon_segments as u16 + 1;
                        indices.push(first);
                        indices.push(first + 1);
                        indices.push(first);
                        indices.push(second);
                    }
                }
                let vertex_buffer = graphics
                    .device
                    .create_buffer_init(
                        &BufferInitDescriptor {
                            label: Some("sphere wireframe vertex buffer"),
                            contents: bytemuck::cast_slice(&vertices),
                            usage: BufferUsages::VERTEX,
                        },
                    );
                let index_buffer = graphics
                    .device
                    .create_buffer_init(
                        &BufferInitDescriptor {
                            label: Some("sphere wireframe index buffer"),
                            contents: bytemuck::cast_slice(&indices),
                            usage: BufferUsages::INDEX,
                        },
                    );
