        fn dropbear_physics_get_gravity(
            physics_ptr: u64,
        ) -> Result<NVector3, crate::scripting::native::DropbearNativeError> {
            let physics = {
                let ptr = physics_ptr as *const PhysicsState;
                if ptr.is_null() {
                    return Err(
                        crate::scripting::native::DropbearNativeError::NullPointer,
                    );
                }
                let addr = ptr as usize;
                let align = std::mem::align_of::<PhysicsState>();
                if addr % align != 0 {
                    return Err(
                        crate::scripting::native::DropbearNativeError::InvalidArgument,
                    );
                }
                unsafe { &*ptr }
            };
            Ok(shared::get_gravity(physics))
        }
        fn dropbear_physics_set_gravity(
            physics_ptr: u64,
            new_gravity: NVector3,
        ) -> Result<(), crate::scripting::native::DropbearNativeError> {
            let mut physics = {
                let ptr = physics_ptr as *mut PhysicsState;
                if ptr.is_null() {
                    return Err(
                        crate::scripting::native::DropbearNativeError::NullPointer,
                    );
                }
                let addr = ptr as usize;
                let align = std::mem::align_of::<PhysicsState>();
                if addr % align != 0 {
                    return Err(
                        crate::scripting::native::DropbearNativeError::InvalidArgument,
                    );
                }
                unsafe { &mut *ptr }
            };
            shared::set_gravity(&mut physics, new_gravity);
            Ok(())
        }
        fn dropbear_physics_raycast(
            physics_ptr: u64,
            origin: NVector3,
            direction: NVector3,
            time_of_impact: f64,
            solid: bool,
        ) -> Result<Option<RayHit>, crate::scripting::native::DropbearNativeError> {
            let physics = {
                let ptr = physics_ptr as *const PhysicsState;
                if ptr.is_null() {
                    return Err(
                        crate::scripting::native::DropbearNativeError::NullPointer,
                    );
                }
                let addr = ptr as usize;
                let align = std::mem::align_of::<PhysicsState>();
                if addr % align != 0 {
                    return Err(
                        crate::scripting::native::DropbearNativeError::InvalidArgument,
                    );
                }
                unsafe { &*ptr }
            };
            let qp = physics
                .broad_phase
                .as_query_pipeline(
                    &DefaultQueryDispatcher,
                    &physics.bodies,
                    &physics.colliders,
                    QueryFilter::new(),
                );
            let ray = Ray::new(
                nalgebra::Point::<_, 3usize> {
                    coords: nalgebra::SVector::<
                        _,
                        3usize,
                    >::from_array_storage(
                        nalgebra::ArrayStorage([
                            [origin.x as f32, origin.y as f32, origin.z as f32],
                        ]),
                    ),
                }
                    .into(),
                nalgebra::SVector::<
                    _,
                    3usize,
                >::from_array_storage(
                        nalgebra::ArrayStorage([
                            [direction.x as f32, direction.y as f32, direction.z as f32],
                        ]),
                    )
                    .into(),
            );
            if let Some((hit, distance)) = qp
                .cast_ray(&ray, time_of_impact as f32, solid)
            {
                let collider = collider_ffi_from_handle(physics, hit);
                Ok(
                    Some(RayHit {
                        collider,
                        distance: distance as f64,
                    }),
                )
            } else {
                Ok(None)
            }
        }
        fn dropbear_physics_shape_cast(
            physics_ptr: u64,
            origin: NVector3,
            direction: NVector3,
            shape: ColliderShapeFFI,
            time_of_impact: f64,
            solid: bool,
        ) -> Result<
            Option<ShapeCastHitFFI>,
            crate::scripting::native::DropbearNativeError,
        > {
            let physics = {
                let ptr = physics_ptr as *const PhysicsState;
                if ptr.is_null() {
                    return Err(
                        crate::scripting::native::DropbearNativeError::NullPointer,
                    );
                }
                let addr = ptr as usize;
                let align = std::mem::align_of::<PhysicsState>();
                if addr % align != 0 {
                    return Err(
                        crate::scripting::native::DropbearNativeError::InvalidArgument,
                    );
                }
                unsafe { &*ptr }
            };
            let qp = physics
                .broad_phase
                .as_query_pipeline(
                    &DefaultQueryDispatcher,
                    &physics.bodies,
                    &physics.colliders,
                    QueryFilter::new(),
                );
            let dir_len = ((direction.x * direction.x) + (direction.y * direction.y)
                + (direction.z * direction.z))
                .sqrt();
            if dir_len <= f64::EPSILON {
                return Ok(None);
            }
            let dir_unit = NVector3 {
                x: direction.x / dir_len,
                y: direction.y / dir_len,
                z: direction.z / dir_len,
            };
            let shape: ColliderShape = shape.into();
            let cast_shape = shared_shape_from_collider_shape(&shape);
            let iso: Pose3 = rapier3d::na::Isometry3::translation(
                    origin.x as f32,
                    origin.y as f32,
                    origin.z as f32,
                )
                .into();
            let vel: Vec3 = nalgebra::SVector::<
                _,
                3usize,
            >::from_array_storage(
                    nalgebra::ArrayStorage([
                        [dir_unit.x as f32, dir_unit.y as f32, dir_unit.z as f32],
                    ]),
                )
                .into();
            let options = ShapeCastOptions {
                max_time_of_impact: time_of_impact as f32,
                target_distance: 0.0,
                stop_at_penetration: solid,
                compute_impact_geometry_on_penetration: true,
            };
            let Some((hit_handle, toi)) = qp
                .cast_shape(&iso, vel, cast_shape.as_ref(), options) else {
                return Ok(None);
            };
            let collider = collider_ffi_from_handle(physics, hit_handle);
            Ok(
                Some(ShapeCastHitFFI {
                    collider,
                    distance: toi.time_of_impact as f64,
                    witness1: NVector3::from([
                        toi.witness1.x,
                        toi.witness1.y,
                        toi.witness1.z,
                    ]),
                    witness2: NVector3::from([
                        toi.witness2.x,
                        toi.witness2.y,
                        toi.witness2.z,
                    ]),
                    normal1: NVector3::from([
                        toi.normal1.x,
                        toi.normal1.y,
                        toi.normal1.z,
                    ]),
                    normal2: NVector3::from([
                        toi.normal2.x,
                        toi.normal2.y,
                        toi.normal2.z,
                    ]),
                    status: toi.status.into(),
                }),
            )
        }
