    use dropbear_engine::texture::Texture;
    use std::collections::HashSet;
    fn texture_handle_id(registry: &AssetRegistry, texture: &Texture) -> Option<u64> {
        texture
            .hash()
            .and_then(|hash| registry.texture_handle_by_hash(hash).map(|h| h.id))
            .filter(|id| *id != 0)
    }
    fn collect_model_texture_handles(
        registry: &AssetRegistry,
        model: &Model,
    ) -> Vec<u64> {
        let mut ids = HashSet::new();
        let mut insert_texture = |texture: &Texture| {
            if let Some(id) = texture_handle_id(registry, texture) {
                ids.insert(id);
            }
        };
        for material in &model.materials {
            insert_texture(&material.diffuse_texture);
            insert_texture(&material.normal_texture);
            if let Some(tex) = &material.emissive_texture {
                insert_texture(tex);
            }
            if let Some(tex) = &material.metallic_roughness_texture {
                insert_texture(tex);
            }
            if let Some(tex) = &material.occlusion_texture {
                insert_texture(tex);
            }
        }
        ids.into_iter().collect()
    }
